 pub fn started(&self)->bool{self.binding.is_some()||!self.birth.terminal_is_empty()||self.unit.is_some()}
 pub fn complete(&self)->bool{self.phase==9}
 pub fn admit(&mut self,ledger:&TypingLedger<A::Mutation>,suppress:bool,all:bool,metadata:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.admit_policy(ledger,suppress,all,true,true,metadata,cx)}
 pub fn control_pass(&self)->bool{self.control}
 pub(crate) fn admit_policy(&mut self,ledger:&TypingLedger<A::Mutation>,suppress:bool,all:bool,control:bool,retire_windows:bool,metadata:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.pending(){self.validate_ledger(ledger,cx)?;if metadata.is_some()||self.control!=control||self.retire_windows!=retire_windows{return Err(invalid().into())}return Ok(true)}if metadata.is_none(){return Err(invalid().into())}if !self.unit(cx,fixed::<Self>())?{return Ok(false)}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;self.decoder=Some(cx.native_receiving_identity().ok_or_else(invalid)?);self.ledger=ledger as*const _ as usize;self.binding=Some(binding);self.body=body;*self.original_metadata=metadata.take();self.suppress=suppress;self.all=all;self.control=control;self.retire_windows=retire_windows;self.phase=11;Ok(true)}
 pub(crate) fn unit(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand)->Result<bool,OriginalTurnFailure>{let ready=self.birth.built(cx,&mut self.unit,construction(d),||Ok(((),receipt(d))))?;if ready{self.unit=None;}Ok(ready)}
 pub fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.is_some_and(|b|b.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(invalid().into())}Ok(())}
 pub(crate) fn validate_ledger(&self,ledger:&TypingLedger<A::Mutation>,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{self.validate(cx)?;if self.ledger!=ledger as*const _ as usize{return Err(invalid().into())}Ok(())}
 /// 🫙️ The actual bound ledger's empty frontier completes selection without inventing a typing row.
 pub fn complete_empty_ledger(&mut self,ledger:&TypingLedger<A::Mutation>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate_ledger(ledger,cx)?;if self.phase!=1||!ledger.is_empty()||self.row.is_some()||self.input.is_some()||self.transaction.is_some()||self.values.is_some()||self.receipt.is_some(){return Err(invalid().into())}self.transition(9,cx)}
 pub(crate) fn skip_unused_clock(&mut self,ledger:&TypingLedger<A::Mutation>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate_ledger(ledger,cx)?;if self.phase!=11||!self.control&&!ledger.is_empty(){return Err(invalid().into())}self.transition(10,cx)}
 pub fn capture_clock(&mut self,now:impl FnOnce()->u64,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=11{return Err(invalid().into())}if !self.unit(cx,fixed::<(u64,u64,u8)>())?{return Ok(false)}self.now=Some(now());self.phase=10;Ok(true)}
 #[cfg(any(test,feature="artifact-app-testing"))]
 pub fn original_metadata_for_testing(&self)->Option<&ActionMeta>{self.original_metadata.as_ref()}
 pub(crate) fn transition(&mut self,phase:u8,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.unit(cx,fixed::<u8>())?{return Ok(false)}self.phase=phase;Ok(true)}
 pub fn admit_parent(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.caller.is_none(){cx.original_source_parent()?.admit_loan(&mut *self.caller,cx)?;return Ok(false)}self.transition(1,cx)}
 pub(crate) fn close_row(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let Some(row)=self.row.as_mut()else{return Ok(true)};if row.terminal_is_empty(){let d=OriginalTypingCommit::<A::Mutation>::release_demands();retired(cx,d,|_|{drop(self.row.take());Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else{row.close_step(cx)?;}Ok(self.row.is_none())}
 pub(crate) fn close_receipt(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.retirement.is_empty(){let d=self.retirement.demands(self.body)?;let body=self.body;retired_poll(cx,d,|effect|self.retirement.step_granted(body,effect))?;return Ok(false)}if self.receipt.is_some(){let d=self.retirement.next_owner_demands::<semio_framework::kernel::InvocationResult>(true,&None,self.body)?;begun(cx,d,|effect|self.retirement.begin_granted(&mut self.receipt,effect))?;return Ok(false)}Ok(true)}
 pub(crate) fn capture_window(&mut self,window:&SharedUtf8,key:semio_framework_value::retained_clone::original_slot::RetainedOriginalSlotKey,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.previous.is_some(){return Ok(false)}if self.captured.is_none(){let mut cloned=None;funded(cx,SharedUtf8::lease_demand(),|effect|{let turn=window.admit_clone(effect);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|(alias,progress)|{cloned=Some(alias);RetainedCloneStep::Progress(progress)}),work:turn.work})})?;*self.captured=cloned;return Ok(false)}if !self.unit(cx,fixed::<(SharedUtf8,SharedUtf8,Option<SharedUtf8>,usize,u8)>())?{return Ok(false)}*self.previous=self.after.take();*self.after=self.captured.take();self.key=Some(key);self.roster=0;self.compared=0;self.phase=2;Ok(true)}
 pub(crate) fn retire_previous(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.retirement.is_empty(){let d=self.retirement.demands(self.body)?;let body=self.body;retired_poll(cx,d,|effect|self.retirement.step_granted(body,effect))?;return Ok(false)}if self.previous.is_some(){let d=self.retirement.next_owner_demands::<SharedUtf8>(true,&None,self.body)?;begun(cx,d,|effect|self.retirement.begin_granted(&mut self.previous,effect))?;return Ok(false)}Ok(true)}
 pub(crate) fn roster_step(&mut self,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{self.validate(cx)?;let Self{original_metadata,after,roster,compared,phase,birth,unit,..}=self;let view=original_metadata.as_ref().and_then(|meta|meta.view_state.as_deref()).ok_or_else(invalid)?;let window=after.as_ref().ok_or_else(invalid)?.as_str();if *roster>view.window_instances.len(){return Err(invalid().into())}if *roster==view.window_instances.len(){return Ok(Some(false))}let candidate=view.window_instances[*roster].id.as_str();if *compared>window.len().min(candidate.len()){return Err(invalid().into())}let d=RetirementDemand{copy_bytes:64+3*size_of::<usize>(),depth:1,..Default::default()};if !birth.built(cx,unit,construction(d),||Ok(((),receipt(d))))?{return Ok(None)}*unit=None;let mut result=None;let end=(*compared+64).min(window.len().min(candidate.len()));let same=window.as_bytes()[*compared..end]==candidate.as_bytes()[*compared..end];if !same||end==window.len().min(candidate.len()){if same&&window.len()==candidate.len(){result=Some(true);*phase=1}else{*roster+=1;*compared=0}}else{*compared=end}Ok(result)}
