 pub(crate) fn prepare_verb(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let tool=&self.transaction.as_ref().ok_or_else(invalid)?.tool;let text=tool.rsplit_once('#').map_or(tool.as_str(),|(_,verb)|verb);if self.verb.is_none(){let d=RetirementDemand{capacity_bytes:text.len(),..fixed::<String>()};self.birth.built(cx,&mut self.verb,construction(d),||Ok((String::with_capacity(text.len()),receipt(d))))?;return Ok(false)}if self.offset<text.len(){let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}let d=RetirementDemand{copy_bytes:end-self.offset+2*size_of::<usize>(),depth:1,..Default::default()};let ready=self.birth.built(cx,&mut self.unit,construction(d),||Ok(((),receipt(d))))?;if ready{self.unit=None;self.verb.as_mut().ok_or_else(invalid)?.push_str(&text[self.offset..end]);self.offset=end;}return Ok(false)}Ok(true)}
