  macro_rules! quote{($field:ident,$ty:ty)=>{if self.$field.is_some(){return self.retirement.next_owner_demands::<$ty>(true,&None,self.body)}}}
  quote!(receipt,semio_framework::kernel::InvocationResult);quote!(previous,SharedUtf8);if !handoff{quote!(original_metadata,ActionMeta);}quote!(input,OriginalEmissionInput<A>);quote!(metadata,ActionMeta);quote!(transaction,protocol::TransactionRef);quote!(values,Vec<A::Mutation>);quote!(verb,String);quote!(captured,SharedUtf8);quote!(after,SharedUtf8);if let Some(caller)=self.caller.as_ref(){return Ok(caller.retirement_demands())}Ok(fixed::<Self>())
