 pub fn finish_into(&mut self,ready:&mut bool,decision:&mut Option<bool>,metadata:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.complete()||metadata.is_some(){return Err(invalid().into())}self.close_received(cx,Some((ready,decision,metadata)))}
